      "verdict": "SUPPORT",
      "reason": "sandbox 接口是查询执行所绑定的接口，不是生成文件或依据材料。",
      "sources": [{"quote": "在 sandbox 接口执行", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
