    },
    {
      "candidate_id": "r1",
      "verdict": "SUPPORT",
      "reason": "PM 明确实施组织动作，PERFORMER 来自动词绑定，而非仅来自角色名称。",
      "sources": [{"quote": "PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r2",
      "verdict": "SUPPORT",
      "reason": "查询执行明确属于所要求组织的内容。",
      "sources": [{"quote": "组织在 sandbox 接口执行恰好 3 次可用性查询", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
