      "sources": [{"quote": "调用生产接口", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r9",
      "verdict": "SUPPORT",
      "reason": "独立禁令在任务层禁止生产接口调用，没有附加条件。",
      "sources": [{"quote": "不得调用生产接口", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "q1",
      "verdict": "SUPPORT",
      "reason": "“恰好 3 次”明确要求查询执行次数等于 3；EQ、execution_count 和 EXECUTION_LIMIT 均有支持。",
      "sources": [{"quote": "执行恰好 3 次可用性查询", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    }
  ],
